import type { BridgeMessagePayload } from "@notionhq/custom-blocks-protocol"
import type { PrimeableHostToSandboxMessage } from "@notionhq/custom-blocks-protocol/messages/hostToSandbox.js"

import { globalPrimedResponsesCache } from "./bridge/primedResponses.js"

/**
 * Injects a one-use response for SDK tests and verification fixtures. The next
 * matching request receives it locally without reaching the host; later requests
 * use the host normally unless another response is primed.
 */
export function primeNextResponse<T extends PrimeableHostToSandboxMessage>({
	expectedType,
	response,
}: {
	expectedType: T["type"]
	response: BridgeMessagePayload<T>
}) {
	globalPrimedResponsesCache.set(expectedType, response)
}
